export function record(state,meta={}){const course=state.course,c=state.courses[course],a=activityFor(course,c.activity),e=c.experiments[a.id];if(e.trials.length>=100)throw Error('trial-limit');const trial={id:e.trials.length+1,at:new Date().toISOString(),labId:'L01',schoolBand:COURSES[course].band,courseId:course,activityId:a.id,inputs:copy(e.inputs),zeroed:e.zeroed,placed:e.placed,...meta,result:meta.simulation?measuredResult(solve(a.id,e.inputs,e),validateObservation(meta.simulation,{id:a.id,kind:instrumentKind(a.id,e.inputs,solve(a.id,e.inputs,e))})):solve(a.id,e.inputs,e)};e.trials.push(trial);return trial;}
